(()=>{const video=document.querySelector('#hero-background');if(!video)return;video.muted=true;video.defaultMuted=true;video.controls=false;let inView=true;function update(){if(document.hidden||!inView){video.pause();return}video.play().catch(()=>{})}new IntersectionObserver(([e])=>{inView=e.isIntersecting;update()},{threshold:.01}).observe(video);document.addEventListener('visibilitychange',update);addEventListener('pagehide',()=>video.pause());update()})();